import{_ as t,o,c as a,a3 as d}from"./chunks/framework.BTQ4eCVb.js";const h=JSON.parse('{"title":"Knowledge Base — Developer Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Knowledge Base — Developer Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/knowledge-base"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Knowledge Base — Developer Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/knowledge-base"}]]},"headers":[],"relativePath":"developer-guide/knowledge-base.md","filePath":"developer-guide/knowledge-base.md","lastUpdated":1787503667000}'),s={name:"developer-guide/knowledge-base.md"};function i(l,e,n,c,r,p){return o(),a("div",null,[...e[0]||(e[0]=[d(`<h1 id="knowledge-base-—-developer-guide" tabindex="-1">Knowledge Base — Developer Guide <a class="header-anchor" href="#knowledge-base-—-developer-guide" aria-label="Permalink to &quot;Knowledge Base — Developer Guide&quot;">​</a></h1><p>Marketplace Operations module (<code>knowledge-base</code> <strong>1.0.0</strong>). Flat namespaces (no <code>Modules/</code> package). Internal workspace articles only — no public portal.</p><h2 id="backend-layout" tabindex="-1">Backend layout <a class="header-anchor" href="#backend-layout" aria-label="Permalink to &quot;Backend layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Path</th></tr></thead><tbody><tr><td>Models</td><td><code>KnowledgeBaseArticle</code>, <code>KnowledgeBaseCategory</code>, <code>KnowledgeBaseArticleNote</code>, <code>KnowledgeBaseArticleActivity</code></td></tr><tr><td>Enums</td><td><code>KnowledgeBaseArticleStatusEnum</code>, <code>KnowledgeBaseArticleActivityTypeEnum</code></td></tr><tr><td>Services</td><td><code>KnowledgeBaseArticleService</code>, <code>KnowledgeBaseCategoryService</code></td></tr><tr><td>Controllers</td><td><code>KnowledgeBaseArticleController</code>, <code>KnowledgeBaseCategoryController</code></td></tr><tr><td>Requests</td><td><code>app/Http/Requests/Tenant/Api/V1/KnowledgeBase*</code>, <code>KnowledgeBaseCategory*</code></td></tr><tr><td>Resources</td><td><code>app/Http/Resources/Tenant/Api/V1/KnowledgeBase*</code>, <code>KnowledgeBaseCategory*</code></td></tr><tr><td>Policies</td><td><code>KnowledgeBaseArticlePolicy</code>, <code>KnowledgeBaseCategoryPolicy</code></td></tr><tr><td>Events</td><td><code>KnowledgeBaseArticleCreated</code>, <code>Updated</code>, <code>Deleted</code>, <code>NoteAdded</code></td></tr><tr><td>Subscriber</td><td><code>KnowledgeBaseArticleEventSubscriber</code> (PlatformAuditService)</td></tr><tr><td>Tests</td><td><code>tests/Feature/Tenant/KnowledgeBase/KnowledgeBaseArticleTest.php</code></td></tr></tbody></table><h2 id="authz-and-visibility" tabindex="-1">Authz and visibility <a class="header-anchor" href="#authz-and-visibility" aria-label="Permalink to &quot;Authz and visibility&quot;">​</a></h2><ul><li>Routes: <code>module:knowledge-base</code> for all endpoints</li><li>Reads: <code>can:knowledge-base.view</code></li><li>Mutations: <code>can:knowledge-base.create|update|delete|restore|force.delete</code> as on each route</li><li>Categories reuse the same <code>knowledge-base.*</code> permissions</li></ul><p><strong>Audience visibility:</strong> actors without <code>knowledge-base.update</code> are limited to <code>scopeVisibleToAudience()</code> (status <code>published</code>). Actors with update may filter <code>status</code> and <code>trashed</code> (<code>only</code> / <code>true</code> / <code>with</code>). Policy <code>view</code> allows update holders any non-gate-failed row; view-only holders only non-trashed published articles.</p><h2 id="date-and-time" tabindex="-1">Date and time <a class="header-anchor" href="#date-and-time" aria-label="Permalink to &quot;Date and time&quot;">​</a></h2><p><code>published_at</code> uses <code>UtcDateTime</code>. API responses serialize absolute datetimes as UTC ISO-8601 (<code>...Z</code> / UtcIso). Publishing sets <code>published_at</code> via <code>now()</code> when transitioning into published with a null stamp; draft clears it.</p><h2 id="domain-rules" tabindex="-1">Domain rules <a class="header-anchor" href="#domain-rules" aria-label="Permalink to &quot;Domain rules&quot;">​</a></h2><ul><li>Slugs unique per tenant for articles and categories</li><li>Category soft/force delete blocked while articles (including trashed for force) still reference the category</li><li>Articles: notes + <code>knowledge_base_article_activities</code> timeline; model uses Spatie <code>LogsActivity</code> (<code>useLogName(&#39;knowledge-base&#39;)</code>)</li><li>Platform audit: <code>knowledge_base_article_created|updated|deleted|note_added</code></li><li>Soft Help Desk backlinks: <code>KnowledgeBaseArticle::helpDeskTickets()</code> — loaded on article show when <code>module:help-desk</code> entitled; exposed as <code>help_desk_tickets</code> on <code>KnowledgeBaseArticleResource</code></li><li>No hard <code>module_dependencies</code></li></ul><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><ul><li>Pages: <code>src/pages/knowledge-base/</code> — article view includes <strong>Linked tickets</strong> when Help Desk is entitled</li><li>Tour: <code>tourId=&quot;knowledge-base&quot;</code> (<code>src/tours/knowledge-base.ts</code>)</li><li>Nav: <code>module:knowledge-base</code> + <code>knowledge-base.view</code></li><li>Playwright: <code>npm run test:e2e:knowledge-base</code></li></ul><h2 id="permissions-config" tabindex="-1">Permissions config <a class="header-anchor" href="#permissions-config" aria-label="Permalink to &quot;Permissions config&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>knowledge-base.view | create | update | delete | restore | force.delete</span></span></code></pre></div><p>Default roles: admin = all except force.delete; manager = view/create/update; staff = view.</p><h2 id="catalog-registration" tabindex="-1">Catalog registration <a class="header-anchor" href="#catalog-registration" aria-label="Permalink to &quot;Catalog registration&quot;">​</a></h2><p>Data migration <code>register_knowledge_base_module</code> (<code>is_default_included: false</code>, <code>is_billable: false</code>, version <code>1.0.0</code>, category <code>operations</code>, sort <code>60</code>) — <strong>no</strong> <code>installForWorkspacesMissingModule</code>. Permissions sync migration grants additive defaults (not <code>force.delete</code>).</p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --compact</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/Feature/Tenant/KnowledgeBase</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:e2e:knowledge-base</span></span></code></pre></div><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/api/tenant-v1-knowledge-base">API</a></li><li><a href="/deployment/knowledge-base">Deployment</a></li><li><a href="/user-guide/knowledge-base">User guide</a></li><li><a href="/developer-guide/module-development">Module development</a></li></ul>`,22)])])}const u=t(s,[["render",i]]);export{h as __pageData,u as default};
